def generator(rng):
    non_squares = [d for d in range(2, 21) if int(d**0.5)**2 != d]
    while True:
        a = rng.randint(1, 4)
        b = rng.randint(1, 4)
        if a == b:
            continue

        D = rng.choice(non_squares)
        p = rng.choice([3, 5])

        if a*a >= b*b*D:
            continue

        K = 2 * (a*a + b*b*D)
        L = (a*a - b*b*D)**2

        if K > 500 or L > 50000:
            continue
        if K <= 10 or L <= 1:
            continue

        # Calculate answer to check magnitude
        S_prev = 2
        S_curr = 2 * a
        if p > 1:
            term1_coeff = 2 * a
            term2_coeff = -(a*a - b*b*D)
            for _ in range(2, p + 1):
                S_next = term1_coeff * S_curr + term2_coeff * S_prev
                S_prev = S_curr
                S_curr = S_next
        answer = S_curr

        if answer < 100 or answer > 20000:
            continue

        return {"K": K, "L": L, "p": p}
